<script setup lang="ts">
import { computed,nextTick,onMounted,onBeforeUnmount,ref,watch } from 'vue'
import InformationRequestThread from './InformationRequestThread.vue'
const props=defineProps<{employee?:{EmployeeID?:number;EmployeeNumber?:string|null;EmployeeName?:string;AgencyName?:string;PositionName?:string}}>()
const emit=defineEmits<{dirty:[value:boolean];processing:[value:boolean]}>()
const fields=ref<any[]>([]),choices=ref<any[]>([]),requests=ref<any[]>([]),pagination=ref({page:1,pages:1,total:0}),loading=ref(false),busy=ref(false),error=ref(''),notice=ref('')
const tab=ref('details'),showForm=ref(false),fieldKey=ref(''),proposedValue=ref(''),message=ref(''),replies=ref<Record<number,string>>({}),opened=ref<number|null>(null),pending=ref<any>(null),requestForm=ref<HTMLElement|null>(null),reviewPanel=ref<HTMLElement|null>(null)
let owner=0,controller:AbortController|null=null
const sections=computed(()=>[...new Set(fields.value.map(field=>field.section))])
const activeRequest=computed(()=>requests.value.find(item=>item.RequestID===opened.value)||requests.value[0])
const preview=(item:any)=>{const last=item.messages?.[item.messages.length-1];return last?(last.Sender==='Staff'?'HR: ':'You: ')+last.Message:'No messages yet'}
const selectedField=computed(()=>fields.value.find(field=>field.key===fieldKey.value))
const value=(key:string)=>fields.value.find(field=>field.key===key)?.value||''
const name=computed(()=>props.employee?.EmployeeName||[value('FirstName'),value('MiddleName'),value('LastName')].filter(Boolean).join(' ')||'Your employee record')
const initials=computed(()=>name.value.split(/\s+/).filter(Boolean).slice(0,2).map(word=>word[0]).join(''))
const identity=computed(()=>props.employee?.EmployeeNumber||value('EmployeeNumber')||(props.employee?.EmployeeID?'EMP-'+String(props.employee.EmployeeID).padStart(4,'0'):''))
const agency=computed(()=>props.employee?.AgencyName||value('AgencyName'))
const position=computed(()=>props.employee?.PositionName||value('PositionName'))
function display(field:any){if(!field.value)return 'Not recorded';if(['Birthday','DateHired'].includes(field.key)&&/^\d{4}-\d{2}-\d{2}$/.test(field.value)){const date=new Date(field.value+'T00:00:00Z');if(Number.isFinite(date.getTime()))return date.toLocaleDateString('en-PH',{month:'long',day:'numeric',year:'numeric',timeZone:'Asia/Singapore'})}return field.value}
const hasDraft=computed(()=>Boolean(proposedValue.value||message.value||Object.values(replies.value).some(Boolean)))
watch(busy,value=>emit('processing',value));watch(hasDraft,value=>emit('dirty',value))
async function load(page=1){const current=++owner;controller?.abort();controller=new AbortController();loading.value=true;error.value='';try{const result:any=await $fetch('/api/employee-portal/information',{query:{page},signal:controller.signal,retry:0,timeout:15000});if(current===owner){fields.value=result.fields;choices.value=result.requestFields;requests.value=result.requests.items;pagination.value=result.requests.pagination}}catch(cause:any){if(current===owner)error.value=cause?.data?.statusMessage||'Unable to load your employee information.'}finally{if(current===owner)loading.value=false}}
async function startRequest(){showForm.value=true;await nextTick();requestForm.value?.scrollIntoView({block:'start',behavior:'smooth'});requestForm.value?.querySelector('select')?.focus({preventScroll:true})}
async function reviewRequest(){pending.value={action:'create',fieldKey:fieldKey.value,proposedValue:proposedValue.value.trim(),message:message.value.trim()};await focusReview()}
async function focusReview(){await nextTick();reviewPanel.value?.scrollIntoView({block:'center',behavior:'smooth'});reviewPanel.value?.focus({preventScroll:true})}
async function reviewMessage(item:any,action:string){pending.value={action,requestId:item.RequestID,version:item.Version,...(action==='message'?{message:(replies.value[item.RequestID]||'').trim()}:{})};await focusReview()}
async function send(){
 if(!pending.value||busy.value)return
 const body={...pending.value},current=owner;busy.value=true;error.value='';notice.value=''
 try{
  const result:any=await $fetch('/api/employee-portal/information',{method:'POST',body,retry:0,timeout:20000});if(current!==owner)return
  pending.value=null
  if(body.action==='create'){proposedValue.value='';message.value='';fieldKey.value='';showForm.value=false;tab.value='requests';opened.value=result.requestId||null}else{delete replies.value[body.requestId]}
  notice.value=body.action==='create'?'Your request was sent to HR. Your employee record has not been changed.':'Request updated.';await load()
 }catch(cause:any){if(current===owner)error.value=cause?.data?.statusMessage||'Unable to send this request.'}finally{busy.value=false}
}
onMounted(()=>void load());onBeforeUnmount(()=>{owner++;controller?.abort();emit('dirty',false);emit('processing',false)})
</script>
<template>
 <section class="information-panel" :aria-busy="loading||busy">
  <header class="information-heading"><div><p class="eyebrow">EMPLOYEE RECORD</p><h2>My information</h2><p>Review your details and request a correction from HR.</p></div><button type="button" class="primary request-start" :disabled="busy||loading||Boolean(pending)" @click="startRequest"><span aria-hidden="true">+</span> Request correction</button></header>
  <p v-if="error" role="alert" class="error">{{error}} <button type="button" :disabled="busy" @click="load(pagination.page)">Reload</button></p><p v-if="notice" role="status" class="success">{{notice}}</p>
  <section class="profile-summary" aria-label="Employee summary"><div class="avatar" aria-hidden="true">{{initials}}</div><div class="profile-identity"><h3>{{name}}</h3><p>{{[identity,position].filter(Boolean).join(' / ')}}</p><p v-if="agency">{{agency}}</p></div><span class="read-only"><svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/></svg>Managed by HR</span></section>
  <nav class="information-tabs" role="tablist" aria-label="Employee information"><button id="information-details-tab" type="button" role="tab" :aria-selected="tab==='details'" aria-controls="information-details" :tabindex="tab==='details'?0:-1" :disabled="busy" @click="tab='details'" @keydown.right.prevent="tab='requests';($event.currentTarget as HTMLElement).nextElementSibling?.focus()">Employee details</button><button id="information-requests-tab" type="button" role="tab" :aria-selected="tab==='requests'" aria-controls="information-requests" :tabindex="tab==='requests'?0:-1" :disabled="busy" @click="tab='requests'" @keydown.left.prevent="tab='details';($event.currentTarget as HTMLElement).previousElementSibling?.focus()">My requests <span>{{pagination.total}}</span></button></nav>
  <p v-if="loading" class="loading" role="status">Loading employee information...</p>
  <div v-show="tab==='details'" id="information-details" role="tabpanel" aria-labelledby="information-details-tab">
   <div class="record-note"><span aria-hidden="true">i</span><p>These details are read-only. HR reviews correction requests before updating your record. <small>Your portal login email and number are managed separately in My account.</small></p></div>
   <div class="information-sections"><section v-for="(section,index) in sections" :key="section"><header class="section-heading"><span class="section-number" aria-hidden="true">{{String(index+1).padStart(2,'0')}}</span><h3>{{section}}</h3></header><dl><div v-for="field in fields.filter(item=>item.section===section)" :key="field.key" :class="{wide:field.key.includes('Address')||field.key==='AgencyName'||field.key==='Email'}"><dt>{{field.label}}</dt><dd :class="{unrecorded:!field.value}">{{display(field)}}</dd></div></dl></section></div>
  </div>
  <section v-show="tab==='requests'" id="information-requests" class="my-requests" role="tabpanel" aria-labelledby="information-requests-tab">
   <header class="requests-heading"><div><h3>Messages with HR</h3><p>Each correction request has its own conversation.</p></div><span class="request-total">{{pagination.total}} request{{pagination.total===1?'':'s'}}</span></header>
   <div v-if="requests.length&&tab==='requests'" class="request-workspace"><aside class="request-inbox" aria-label="Correction requests"><p class="inbox-label">YOUR REQUESTS</p><button v-for="item in requests" :key="item.RequestID" type="button" class="request-heading" :class="{active:activeRequest?.RequestID===item.RequestID}" :aria-pressed="activeRequest?.RequestID===item.RequestID" :disabled="busy||Boolean(pending)" @click="opened=item.RequestID"><span class="request-row-title"><strong>{{item.FieldLabel}}</strong><span class="request-state" :class="{resolved:item.Status==='Resolved'}">{{item.Status}}</span></span><span class="request-preview">{{preview(item)}}</span><small>Request #{{item.RequestID}}</small></button></aside>
    <div v-if="activeRequest" class="request-content"><InformationRequestThread :request="activeRequest"><template #composer><form v-if="['Pending','In review'].includes(activeRequest.Status)&&!pending" class="conversation-reply" @submit.prevent="reviewMessage(activeRequest,'message')"><label>Follow-up message<textarea v-model="replies[activeRequest.RequestID]" required maxlength="2000" rows="2" :disabled="busy" placeholder="Write a message to HR..."></textarea></label><div class="composer-actions"><small>Review your message before sending.</small><div class="actions"><button type="button" class="quiet" :disabled="busy" @click="reviewMessage(activeRequest,'cancel')">Cancel request</button><button type="submit" class="primary" :disabled="busy">Review message <span aria-hidden="true">&#8599;</span></button></div></div></form><p v-else-if="!pending" class="closed-conversation">This request is {{activeRequest.Status.toLowerCase()}}. You can read the conversation here.</p><p v-else class="closed-conversation">Review and confirm your message below before sending.</p></template></InformationRequestThread></div>
   </div>
   <div v-if="!requests.length&&!loading" class="empty"><span aria-hidden="true">&#10003;</span><h4>No conversations yet</h4><p>Use Request correction to send HR a question about your recorded details.</p></div>
   <div v-if="pagination.pages>1" class="pages"><button type="button" :disabled="loading||busy||pagination.page<=1||Boolean(pending)" @click="load(pagination.page-1)">Previous</button><small>{{pagination.page}} / {{pagination.pages}}</small><button type="button" :disabled="loading||busy||pagination.page>=pagination.pages||Boolean(pending)" @click="load(pagination.page+1)">Next</button></div>
  </section>
  <section v-show="showForm" ref="requestForm" class="new-request"><header class="requests-heading"><div><p class="eyebrow">CONTACT HR</p><h3>Request an information correction</h3><p>Choose the detail and explain what should be corrected.</p></div><button type="button" :disabled="busy||Boolean(pending)" @click="showForm=false">Hide form</button></header><form @submit.prevent="reviewRequest"><fieldset :disabled="busy||Boolean(pending)"><label>Information to correct<select v-model="fieldKey" required><option value="" disabled>Choose information</option><option v-for="field in choices" :key="field.key" :value="field.key">{{field.label}}</option></select></label><div v-if="selectedField" class="recorded"><span>Currently recorded</span><strong>{{display(selectedField)}}</strong></div><label>Correct information<textarea v-model="proposedValue" required maxlength="2000" rows="2" placeholder="Enter the correct detail"></textarea></label><label>Message to HR<textarea v-model="message" required maxlength="2000" rows="3" placeholder="Please explain the correction you are requesting."></textarea></label><p class="form-note">Do not include passwords, recovery codes or full ID document numbers. Your record changes only after HR reviews and updates it.</p><button class="primary" type="submit">Review request</button></fieldset></form></section>
  <p v-if="!showForm&&(proposedValue||message)" class="draft-note">You have an unsent correction request. <button type="button" :disabled="busy" @click="startRequest">Continue editing</button></p>
  <section v-if="pending" ref="reviewPanel" class="review" aria-label="Review correction request" tabindex="-1"><p class="eyebrow">CONFIRMATION</p><h3>{{pending.action==='create'?'Review your request':pending.action==='cancel'?'Cancel this request?':'Send this follow-up message?'}}</h3><div v-if="pending.action==='create'" class="review-value"><span>{{choices.find(field=>field.key===pending.fieldKey)?.label}}</span><strong>{{pending.proposedValue}}</strong></div><p>{{pending.action==='cancel'?'HR will see that you cancelled this request. Your employee record will not be changed.':pending.message}}</p><p v-if="pending.action==='create'" class="form-note">This sends a request to HR. It does not change your employee details.</p><div class="actions"><button type="button" :disabled="busy" @click="pending=null">Keep editing</button><button type="button" class="primary" :disabled="busy" @click="send">{{busy?'Sending...':'Confirm and send'}}</button></div></section>
 </section>
</template>
<style scoped>
