in-width:0}.request-heading strong{display:block;font-size:.82rem}.request-heading small{display:block;font-size:.66rem;color:#8294ab;font-weight:400;margin-top:6px}.request-state{font-size:.64rem;color:#98691b;background:#fff4dc;padding:5px 8px;border-radius:5px;white-space:nowrap}.request-state.resolved{color:#23704c;background:#e5f6ed}.chevron{font-size:1.05rem;font-weight:400;color:#8496af}.request-content{padding:0 24px 24px}.empty{text-align:center;padding:30px 24px 42px;color:#8193aa}.empty>span{display:grid;place-items:center;background:#f1f6fc;border-radius:12px;width:44px;height:44px;margin:0 auto 14px;color:#6693bf}.empty h4{font-size:.9rem;color:#496587;margin-bottom:8px}.empty p{font-size:.77rem;line-height:1.7}.new-request{margin-top:24px;scroll-margin-top:20px}.new-request form{padding:0 24px 24px;margin:0}form,fieldset{display:grid;gap:16px}form{margin-top:18px}fieldset{border:0;padding:0;margin:0;min-width:0}fieldset>button{justify-self:start}label{display:grid;gap:8px;font-size:.75rem;font-weight:700;color:#4f6888}select,textarea{width:100%;max-width:100%;min-width:0;border:1px solid #cbd8eb;border-radius:7px;padding:11px 12px;background:#fff;color:#203e65;font:inherit;font-size:.87rem}textarea{resize:vertical}.recorded,.review-value{display:grid;gap:6px;background:#f5f8fc;padding:14px 16px;border-radius:7px;overflow-wrap:anywhere;white-space:pre-wrap}.recorded span,.review-value span{font-size:.69rem;color:#768ca7}.recorded strong,.review-value strong{font-size:.83rem;font-weight:500;line-height:1.7}.form-note{font-size:.71rem;color:#788ba3;line-height:1.7}.review{background:#fff;border:1px solid #aac4eb;border-radius:12px;padding:24px;margin-top:24px;scroll-margin:20px;overflow-wrap:anywhere}.review h3{font-size:1.05rem;margin:9px 0 18px}.review>p:not(.eyebrow){white-space:pre-wrap;line-height:1.8;font-size:.82rem;margin:15px 0}.review>p.form-note{font-size:.73rem}.actions,.pages{display:flex;flex-wrap:wrap;gap:10px}.quiet{border-color:transparent;background:transparent;color:#8492a5}.pages{align-items:center;justify-content:flex-end;padding:18px 24px;border-top:1px solid #e6edf7}.error,.success,.draft-note{padding:13px 15px;border-radius:8px;font-size:.79rem;line-height:1.7;background:#fff0f0;color:#a52c38;margin:16px 0}.success{background:#eaf8ef;color:#246f4b}.draft-note{background:#edf3fc;color:#4e6f99}.draft-note button{background:transparent;border:0;padding:0 6px}.loading{font-size:.78rem;color:#748aa5;margin-bottom:14px}button:focus-visible,select:focus-visible,textarea:focus-visible,.review:focus-visible{outline:3px solid #adc9f4;outline-offset:3px}
